<?php defined('BASEPATH') OR exit('No direct script access allowed');$compra_integrada=!empty($compra_integrada);$editable=$compra->estado==='borrador';$aprobada=$compra->estado==='aprobada';$puede_aprobar=!empty($puede_aprobar_compra);$estados_oc=array('borrador'=>'Borrador','aprobada'=>'Aprobada','recibida'=>'Recibida');$pendientes=0;foreach($detalles as $d)if(!($d->conteo_actual ?? $d->stock_confirmado))$pendientes++; $despachadas=0; foreach($asignaciones as $a) if(!empty($a->despacho_id)) $despachadas++; ?>
<?php
$acciones_cabecera=array(array('texto'=>'Volver','icono'=>'mdi-arrow-left','clase'=>'btn-light','aria'=>'Volver a administración','url'=>site_url('almacen/revision_asignaciones').'?periodo='.rawurlencode($compra->periodo)), array('texto'=>'Imprimir','icono'=>'mdi-printer','url'=>site_url('almacen/imprimir_compra/'.$compra->id),'documento'=>true,'nueva_pestana'=>true), array('texto'=>'Excel','icono'=>'mdi-file-excel','url'=>site_url('almacen/exportar_compra/'.$compra->id),'documento'=>true,'aria'=>'Exportar orden de compra a Excel'));
if($compra_integrada) array_shift($acciones_cabecera);
// Borrador: se edita y Administración aprueba. Aprobada: Almacén confirma la recepción; Administración puede reabrirla.
if($editable) {
    $acciones_cabecera[]=array('texto'=>'Guardar','aria'=>'Guardar cantidades de compra','icono'=>'mdi-content-save','form'=>'form-compra','name'=>'accion','value'=>'guardar','clase'=>'btn-secondary');
    if($puede_aprobar) $acciones_cabecera[]=array('texto'=>'Aprobar orden','aria'=>'Aprobar la orden de compra','icono'=>'mdi-check-decagram','form'=>'form-compra','name'=>'accion','value'=>'aprobar','clase'=>'btn-success');
}
if($aprobada) {
    if($puede_aprobar) $acciones_cabecera[]=array('texto'=>'Reabrir','aria'=>'Reabrir la orden como borrador','icono'=>'mdi-lock-open-variant','form'=>'form-compra','name'=>'accion','value'=>'reabrir','clase'=>'btn-light');
    $acciones_cabecera[]=array('texto'=>'Recibir compra','aria'=>'Registrar recepción de la compra','icono'=>'mdi-check','form'=>'form-compra','name'=>'accion','value'=>'recibir','clase'=>'btn-primary');
}
$this->load->view('almacen/cabecera', array('cabecera_titulo'=>'Orden '.Almacen_compras_model::codigo($compra).' · '.$estados_oc[$compra->estado], 'cabecera_acciones'=>$acciones_cabecera));
?>
<?php if(!$compra_integrada): foreach(array('almacen_ok'=>'success','almacen_error'=>'danger') as $key=>$class):if($m=$this->session->flashdata($key)): ?><div class="alert alert-<?= $class ?>"><?= html_escape($m) ?></div><?php endif;endforeach; endif; ?>
<?php if($pendientes): ?><div class="alert alert-warning" role="status"><strong><?= $pendientes ?> producto<?= $pendientes>1?'s':'' ?> sin conteo físico.</strong> <?= $editable||$aprobada?'Al recibir, marca «No había stock» en los que no tenían existencias antes de esta compra; los que no marques no se podrán despachar hasta registrar su conteo en Productos.':'No se pueden despachar hasta registrar su conteo físico en Productos.' ?></div><?php endif; ?>
<?php if($editable && !$puede_aprobar): ?><div class="alert alert-info" role="status"><strong>Pendiente de aprobación de Administración.</strong> Cuando la aprueben podrás confirmar la recepción.</div><?php endif; ?>
<?php if($aprobada): ?><div class="alert alert-success" role="status"><strong>Aprobada<?= !empty($aprobador)?' por '.html_escape($aprobador):'' ?></strong> el <?= html_escape(date('d/m/Y H:i',strtotime($compra->aprobado_en))) ?>. Almacén debe confirmar la recepción cuando llegue la compra; las cantidades aprobadas no se modifican.</div><?php endif; ?>
<?php if($editable && !empty($nuevas_compra)): ?><div class="alert alert-info" role="status"><?= (int)$nuevas_compra ?> asignaci<?= $nuevas_compra>1?'ones aprobadas nuevas no están':'ón aprobada nueva no está' ?> en esta orden. Pulsa <strong>Actualizar consolidado</strong> para incluirla<?= $nuevas_compra>1?'s':'' ?> antes de aprobar.</div><?php endif; ?>
<?php if($editable): ?><div id="almacen-compra-despachos" class="alert alert-warning" role="status" <?= !$despachadas?'hidden':'' ?>>Hay asignaciones despachadas. Actualiza el consolidado antes de aprobar.</div><?php endif; ?>
<?= form_open('almacen/guardar_compra',array('id'=>'form-compra','data-guardar-formulario'=>$editable?'1':'0','data-orden'=>Almacen_compras_model::codigo($compra))) ?><input type="hidden" name="token" value="<?= html_escape($token) ?>"><input type="hidden" name="id" value="<?= (int)$compra->id ?>"><input type="hidden" name="revision" value="<?= (int)$compra->revision ?>">
<div class="card-box"><div class="row"><div class="col-md-8 form-group"><label for="proveedor">Proveedor</label><input class="form-control" id="proveedor" name="proveedor" maxlength="200" value="<?= html_escape($compra->proveedor) ?>" <?= !$editable?'readonly':'' ?>></div><div class="col-md-4"><label>Total de compra (precios con IGV)</label><span id="estado-compra" class="asignacion-guardado" role="status">Versión guardada</span><h3>S/ <span id="total-compra"><?= number_format($compra->total,2) ?></span></h3></div></div>
<div class="compra-vista-barra">
    <h5 id="compra-vista-titulo">Consolidado</h5>
    <div class="custom-control almacen-switch">
        <input type="checkbox" class="custom-control-input" id="ver-clientes-compra" role="switch" aria-controls="compra-consolidado compra-clientes">
        <label class="custom-control-label" for="ver-clientes-compra">Por cliente</label>
    </div>
</div>
<div class="table-responsive" id="compra-consolidado"><table class="table table-sm table-bordered"><thead><tr><th>Producto</th><th>Unidad</th><th>Marca</th><th>Solicitado</th><th>Stock al consolidar</th><th>Sugerido</th><th>A adquirir</th><th>Precio con IGV S/</th><th>Total S/</th></tr></thead><tbody><?php foreach($detalles as $d): ?><tr class="compra-linea" data-producto="<?= html_escape($d->descripcion) ?>" data-unidad="<?= html_escape($d->unidad) ?>" data-precio="<?= html_escape($d->precio_real) ?>"><td><?= html_escape($d->descripcion) ?></td><td><?= html_escape($d->unidad) ?></td><td><?= html_escape($d->marca) ?></td><td class="text-right"><?= number_format($d->solicitado,3) ?></td><td class="text-right"><?php if($d->stock_confirmado): ?><?= number_format($d->stock_disponible,3) ?><?php elseif($d->conteo_actual ?? 0): ?><span class="small text-muted">Contado después</span><?php else: ?><span class="badge badge-warning">Sin conteo</span><?php if($aprobada): ?><div class="custom-control custom-checkbox compra-sin-stock"><input type="checkbox" class="custom-control-input" id="sin-stock-<?= (int)$d->producto_id ?>" name="sin_stock_previo[<?= (int)$d->producto_id ?>]" value="1"><label class="custom-control-label" for="sin-stock-<?= (int)$d->producto_id ?>">No había stock</label></div><?php endif; ?><?php endif; ?></td><td class="text-right"><?= number_format(max(0,$d->solicitado-$d->stock_disponible),3) ?></td><td class="text-right"><label class="sr-only" for="compra-<?= (int)$d->producto_id ?>">Cantidad a adquirir de <?= html_escape($d->descripcion) ?></label><input class="form-control form-control-sm cantidad-compra" style="width:100px" id="compra-<?= (int)$d->producto_id ?>" name="cantidades[<?= (int)$d->producto_id ?>]" type="number" inputmode="decimal" min="0" max="999999999.999" step="0.001" required value="<?= html_escape($d->cantidad) ?>" <?= !$editable?'readonly':'' ?>></td><td class="text-right"><?= number_format($d->precio_real,2) ?></td><td class="importe-compra text-right"><?= number_format($d->total,2) ?></td></tr><?php endforeach; ?></tbody></table></div>
<div class="table-responsive" id="compra-clientes" role="region" aria-label="Solicitado por cliente" tabindex="0" hidden><?php $this->load->view('almacen/compra_clientes',array('detalles'=>$detalles,'asignaciones'=>$asignaciones,'cantidades_clientes'=>$cantidades_clientes)); ?></div>
<div class="form-group"><label for="observaciones">Observaciones</label><textarea class="form-control" id="observaciones" name="observaciones" maxlength="1000" rows="2" <?= !$editable?'readonly':'' ?>><?= html_escape($compra->observaciones) ?></textarea></div>
<?php if($compra->estado==='recibida'): ?><div class="alert alert-success">Recibida el <?= html_escape($compra->recibido_en) ?>.</div><?php endif; ?></div><?= form_close() ?>
<div class="card-box"><div class="d-flex justify-content-between align-items-center flex-wrap"><h4>Asignaciones incluidas (<?= count($asignaciones) ?>)</h4><?php if($editable): ?><?= form_open('almacen/consolidar_compras',array('data-actualizar-consolidado'=>'1')) ?><input type="hidden" name="token" value="<?= html_escape($token) ?>"><input type="hidden" name="periodo" value="<?= html_escape($compra->periodo) ?>"><button class="btn btn-outline-secondary">Actualizar consolidado</button><?= form_close() ?><?php endif; ?></div><ul><?php foreach($asignaciones as $a): ?><li data-compra-asignacion-id="<?= (int)$a->id ?>"><a href="<?= site_url('almacen/revisar_asignacion/'.$a->id) ?>"><?= html_escape($a->nombre) ?></a> · S/ <?= number_format($a->total,2) ?><?php if(!empty($a->despacho_id)): ?> <span class="badge badge-info">Despachada</span><?php endif; ?></li><?php endforeach; ?></ul></div>
